import type { FrameworkApiLearningLevel, FrameworkApiParameter, FrameworkApiReference } from '../types'

type Input = {
  name: string; group: string; kind: FrameworkApiReference['kind']; signature: string
  beginner: string; when: string; example: string; returns: string; principle: string; pitfall: string
  url: string; level: FrameworkApiLearningLevel; runtime: FrameworkApiReference['runtime']
  parameters: FrameworkApiParameter[]; related: string[]; maturity?: FrameworkApiReference['maturity']
}

const p = (name: string, type: string, required: boolean, description: string, defaultValue?: string): FrameworkApiParameter => ({
  name, type, required, description, ...(defaultValue === undefined ? {} : { defaultValue }),
})

function api(input: Input): FrameworkApiReference {
  const officialUrl = input.url
    .replace('/router/latest/docs/framework/react/api/router/', '/router/latest/docs/api/router/')
    .replace('/api/router/RouterProviderComponent', '/framework/react/overview')
    .replace('/api/router/LinkComponent', '/api/router/linkComponent')
    .replace('/api/router/OutletComponent', '/api/router/outletComponent')
    .replace('/api/router/NavigateComponent', '/api/router/navigateComponent')
    .replace('/api/router/CatchBoundaryComponent', '/api/router/catchBoundaryComponent')
    .replace('/virtual/latest/docs/api/react-virtual', '/virtual/latest/docs/framework/react/react-virtual')
    .replace('/query/v5/docs/framework/react/reference/hydration', '/query/latest/docs/framework/react/reference/hydration')
  return {
    slug: `tanstack-${input.name.replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '').toLowerCase()}`,
    technologySlug: 'tanstack', name: input.name, group: input.group, kind: input.kind,
    maturity: input.maturity ?? 'stable', signature: input.signature,
    beginner: input.beginner, whenToUse: input.when, example: input.example, exampleLanguage: 'tsx',
    returns: input.returns,
    interview: `${input.principle} 面试时应先说明它属于哪一个 TanStack 包、管理的是哪种状态，以及取消、缓存、SSR 或权限边界，而不是把 TanStack 误说成一个单体框架。`,
    pitfall: input.pitfall, officialUrl,
    learningLevel: input.level, runtime: input.runtime, parameters: input.parameters,
    expectedOutput: input.returns,
    errorCases: [{ condition: input.pitfall.split('。')[0], handling: `${input.pitfall} 使用固定样例覆盖成功、失败、取消和并发路径，再通过浏览器或服务端集成测试确认实际行为。` }],
    relatedApis: input.related,
  }
}

