const virtualApis = [
  api({ name: 'useVirtualizer', group: 'Virtual v3 · 元素滚动', kind: 'hook', signature: 'useVirtualizer(options): Virtualizer', level: 'core', runtime: 'client', beginner: '创建基于某个滚动元素的虚拟化器，只计算并渲染可视范围附近 items；应用用 transform/position 把真实项放到总尺寸容器中。', when: '长列表、表格或网格有成百上千项，完整 DOM 渲染影响性能时。', example: `const rowVirtualizer = useVirtualizer({ count: rows.length, getScrollElement: () => parentRef.current, estimateSize: () => 44, overscan: 6 })`, returns: '返回 Virtualizer 实例，提供虚拟项、总尺寸、测量与滚动控制；它不渲染任何 DOM。', principle: '虚拟化减少 DOM，不减少服务端数据量；分页/无限查询和虚拟窗口解决不同问题。', pitfall: '滚动容器不稳定或 estimateSize 偏差会跳动；SSR 首屏需提供 initialRect/offset 等一致策略。', url: `${V}/api/react-virtual#usevirtualizer`, parameters: [p('count', 'number', true, '当前可虚拟化项目总数，数据变化时必须同步。'), p('getScrollElement', '() => Element | null', true, '返回稳定滚动容器，挂载前允许 null。'), p('estimateSize', '(index) => number', true, '提供接近真实像素的尺寸估计，动态项后续可 measure。'), p('overscan', 'number', false, '视口外额外渲染项数，在滚动空白和 DOM 数间平衡。')], related: ['Virtualizer', 'Virtualizer.getVirtualItems', 'Virtualizer.getTotalSize'] }),
  api({ name: 'useWindowVirtualizer', group: 'Virtual v3 · Window 滚动', kind: 'hook', signature: 'useWindowVirtualizer(options): Virtualizer<Window, Element>', level: 'core', runtime: 'client', beginner: '使用浏览器 window 作为滚动容器的 React hook，不需要 getScrollElement；列表起点不在页面顶部时要正确处理 scrollMargin。', when: '整页长列表随 window 滚动，而不是在固定高度面板中滚动时。', example: `const v = useWindowVirtualizer({ count: items.length, estimateSize: () => 80, scrollMargin: listRef.current?.offsetTop ?? 0 })`, returns: '返回 Window Virtualizer，提供同样虚拟项、总尺寸和滚动 APIs。', principle: 'window 坐标与列表内部坐标不同，scrollMargin 把两者对齐。', pitfall: '忽略头部高度/scrollMargin 会导致 transform 错位；服务端渲染不能直接读取 window。', url: `${V}/api/react-virtual#usewindowvirtualizer`, parameters: [p('count', 'number', true, '当前页面长列表中参与虚拟计算的项目总数量。'), p('estimateSize', 'function', true, '估计每项尺寸用于初次布局。'), p('scrollMargin', 'number', false, '列表相对 window 顶部的偏移，用于正确转换位置。')], related: ['useVirtualizer', 'Virtualizer.scrollToIndex', 'Virtualizer.getVirtualItems'] }),
  api({ name: 'Virtualizer', group: 'Virtual v3 · 核心实例', kind: 'class', signature: 'new Virtualizer(options)', level: 'advanced', runtime: 'client', beginner: '框架无关的虚拟化核心实例，维护尺寸缓存、可视 range、滚动方向和测量；React 项目通常优先用 useVirtualizer 管理生命周期。', when: '编写自定义适配器、非 React 集成或需要理解低层配置时。', example: `const virtualizer = new Virtualizer(options)`, returns: '返回有状态 Virtualizer；调用方必须更新 options、挂载 observers 并在生命周期结束时清理。', principle: '核心算法依赖真实滚动观测和尺寸缓存，React hook 只是生命周期适配。', pitfall: '直接 new 却不清理 Resize/Scroll observers 会泄漏；普通 React 组件无需绕过 hook。', url: `${V}/api/virtualizer`, parameters: [p('count', 'number', true, '参与窗口计算和尺寸缓存的虚拟项目总数量。'), p('getScrollElement', 'function', true, '返回当前虚拟列表使用的稳定滚动容器元素。'), p('estimateSize', 'function', true, '在实际测量前估计项目尺寸。')], related: ['useVirtualizer', 'Virtualizer.getVirtualItems', 'Virtualizer.scrollToIndex'] }),
  api({ name: 'Virtualizer.getVirtualItems', group: 'Virtual v3 · 读取窗口', kind: 'function', signature: 'virtualizer.getVirtualItems(): VirtualItem[]', level: 'core', runtime: 'client', beginner: '读取当前应挂载的虚拟项；每项含 index、key、start、size、end、lane，用来定位真实 React 元素。', when: 'render 中遍历可视窗口并按 start 做绝对定位或 transform 时。', example: `virtualizer.getVirtualItems().map(v => <div key={v.key} style={{ transform: 'translateY(' + v.start + 'px)' }} />)`, returns: '返回当前视口加 overscan 的 VirtualItem 数组，而不是完整数据列表。', principle: 'VirtualItem 只是布局元数据，业务内容仍按 item.index 从稳定数据源读取。', pitfall: '使用 index 当业务 key 会在插入/排序后复用错误 DOM；应配置 getItemKey。', url: `${V}/api/virtualizer#getvirtualitems`, parameters: [p('当前 range', 'Virtualizer state', true, '根据滚动位置、尺寸缓存和 overscan 计算。'), p('item.index', 'number', true, '映射到当前数据数组位置，不等同稳定业务 ID。'), p('item.start / size', 'number', true, '用于绝对定位与元素占位的像素数据。')], related: ['useVirtualizer', 'Virtualizer.getTotalSize', 'table.getRowModel'] }),
  api({ name: 'Virtualizer.getTotalSize', group: 'Virtual v3 · 读取窗口', kind: 'function', signature: 'virtualizer.getTotalSize(): number', level: 'advanced', runtime: 'client', beginner: '返回全部虚拟项的估计/测量总像素尺寸，用作内部占位容器高度或宽度，让滚动条表示完整列表。', when: '构建绝对定位虚拟列表的 spacer 容器时。', example: `<div style={{ height: virtualizer.getTotalSize() }} />`, returns: '返回总尺寸数字；动态测量完成后可能变化，不代表业务数据条数。', principle: '占位总尺寸维持浏览器滚动范围，可视 DOM 只是其中一个窗口。', pitfall: '把总尺寸固定缓存会让动态行溢出；横向虚拟化要使用宽度而不是高度。', url: `${V}/api/virtualizer#gettotalsize`, parameters: [p('尺寸缓存', 'measurements cache', true, '由估计值与已经测量的真实项目共同计算。')], related: ['Virtualizer.getVirtualItems', 'useVirtualizer', 'Virtualizer.scrollToIndex'] }),
  api({ name: 'Virtualizer.scrollToIndex', group: 'Virtual v3 · 滚动控制', kind: 'function', signature: 'virtualizer.scrollToIndex(index, options?): void', level: 'core', runtime: 'client', beginner: '按项目索引滚动到目标位置，可设置 start/center/end/auto 对齐与 smooth 行为；动态尺寸时可能经过估计再校正。', when: '跳到搜索结果、恢复选中行或键盘导航大列表时。', example: `virtualizer.scrollToIndex(selectedIndex, { align: 'center' })`, returns: '无业务返回值；请求滚动容器移动，实际位置受动态测量、浏览器和用户滚动影响。', principle: '索引滚动依赖当前排序后的数据视图，业务 ID 必须先映射为当前 index。', pitfall: '数据更新后使用旧 index 会跳错项；动态元素配 smooth scroll 可能不稳定，需按官方限制测试。', url: `${V}/api/virtualizer#scrolltoindex`, parameters: [p('index', 'number', true, '当前数据/行模型中的目标位置，必须在 count 范围内。'), p('align', 'auto | start | center | end', false, '控制目标在视口中的对齐方式。', 'auto'), p('behavior', 'auto | smooth', false, '控制滚动行为；动态测量场景 smooth 可能产生偏差。')], related: ['Virtualizer.getVirtualItems', 'Virtualizer.getTotalSize', 'useWindowVirtualizer'] }),
]

